<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\{User,Notification};use Illuminate\Support\Facades\Hash;
class NotificationTest extends TestCase{use RefreshDatabase;private function user(){return User::create(['name'=>'User','phone'=>'+201'.random_int(100000000,999999999),'password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);}protected function setUp():void{parent::setUp();$this->artisan('migrate');}
public function test_notification_creation():void{$u=$this->user();$n=app(\App\Services\NotificationService::class)->create($u,'ADMIN_MESSAGE','Hello','Test', ['x'=>1]);$this->assertDatabaseHas('notifications',['id'=>$n->id,'user_id'=>$u->id]);}
public function test_user_views_own_and_unread_count():void{$u=$this->user();Notification::create(['user_id'=>$u->id,'type'=>'ADMIN_MESSAGE','title'=>'Hi','message'=>'Message']);$this->actingAs($u,'api')->getJson('/api/v1/notifications')->assertOk();$this->actingAs($u,'api')->getJson('/api/v1/notifications/unread-count')->assertOk()->assertJsonPath('data.count',1);}
public function test_cannot_view_others_and_can_mark_read():void{$a=$this->user();$b=$this->user();$n=Notification::create(['user_id'=>$a->id,'type'=>'ADMIN_MESSAGE','title'=>'Hi','message'=>'Message']);$this->actingAs($b,'api')->putJson("/api/v1/notifications/$n->id/read")->assertNotFound();$this->actingAs($a,'api')->putJson("/api/v1/notifications/$n->id/read")->assertOk();$this->assertNotNull($n->fresh()->read_at);}}
